sem_t access_sem;
int shared_data = 0;

// Initialize semaphore: Pshared=0, Initial Value=1 (Mutex-like)
sem_init(&access_sem, 0, 1);

void safe_access() {
    // Wait (P operation): Decrements count, blocks if count is zero
    sem_wait(&access_sem);

    // --- CRITICAL SECTION START ---
    shared_data += 10;
    // --- CRITICAL SECTION END ---

    // Post (V operation): Increments count, wakes waiting thread
    sem_post(&access_sem);
}

// Cleanup: sem_destroy(&access_sem);
